import { cx as cn } from "@/lib/cx";
import { site } from "@/content/site";
import { LOCKUP, MARK_PATH, WORDMARK_PATH } from "./logo-paths";

/**
 * The canonical Presence Hospitality logo (geometry in logo-paths.ts, generated by
 * scripts/generate-logo.mjs; the same paths produce the files in public/brand for Canva and PDFs).
 *
 * The paths live once per page in <LogoSymbols /> (rendered by each root layout); every logo is a
 * small <use> of them, so the outlined wordmark is not repeated in the HTML, the RSC payload or JS.
 *
 * Colour: one ink on light backgrounds (--logo-ink), white on dark (--logo-ink-inverse). By default
 * the logo follows its context (--ui-logo, set per theme in kit.css); `on` forces one of the two.
 * Never recolour, outline, rotate, stretch or add effects. Rules: LOGO_RULES below.
 */

export const LOGO_RULES = {
  /** Clear space on every side, as a fraction of the mark's height. */
  clearSpace: 0.5,
  /** Minimum sizes. Below these, use the mark alone (lockup) or nothing (mark). */
  minLockupWidthPx: 120,
  minMarkPx: 16,
  minLockupWidthMm: 30,
  minMarkMm: 6,
} as const;

const MARK_ID = "ph-logo-mark";
const LOCKUP_ID = "ph-logo-lockup";
const k = LOCKUP.mark.size / 100;
// The referencing <svg>s use a viewBox at the origin: <use> places a symbol's viewport at (0, 0), and
// each symbol maps its own (offset) viewBox into it.

type On = "auto" | "light" | "dark";
const INK: Record<On, string> = {
  auto: "text-ui-logo",
  light: "text-logo-ink",
  dark: "text-logo-ink-inverse",
};

/** The logo's paths, once per page. Rendered by each root layout, before any <Logo />. */
export function LogoSymbols() {
  return (
    <svg aria-hidden width="0" height="0" className="absolute h-0 w-0 overflow-hidden">
      <symbol id={MARK_ID} viewBox="-50 -50 100 100">
        <path fillRule="evenodd" d={MARK_PATH} />
      </symbol>
      <symbol id={LOCKUP_ID} viewBox={LOCKUP.viewBox}>
        <path fillRule="evenodd" transform={`translate(${LOCKUP.mark.cx} ${LOCKUP.mark.cy}) scale(${k})`} d={MARK_PATH} />
        <path d={WORDMARK_PATH} />
      </symbol>
    </svg>
  );
}

/** The mark alone (icon-only version). Square; size it with height/width classes. */
export function LogoMark({
  className,
  on = "auto",
  title,
}: {
  className?: string;
  on?: On;
  /** Accessible name when the mark stands alone as a link or image; omit when decorative. */
  title?: string;
}) {
  return (
    <svg
      viewBox="0 0 100 100"
      fill="currentColor"
      className={cn("shrink-0 overflow-visible", INK[on], className ?? "h-6 w-6")}
      role={title ? "img" : undefined}
      aria-hidden={title ? undefined : true}
      aria-label={title}
    >
      <use href={`#${MARK_ID}`} />
    </svg>
  );
}

/** Mark + wordmark. Height sets the size (default 24px ≈ 22px wordmark); width follows. */
export function Logo({
  className,
  on = "auto",
  decorative = false,
}: {
  className?: string;
  on?: On;
  /** True when a visible label next to it already names the brand. */
  decorative?: boolean;
}) {
  return (
    <svg
      viewBox={`0 0 ${LOCKUP.width} ${LOCKUP.height}`}
      // If a flex/grid parent stretches the box, keep the drawing left-aligned.
      preserveAspectRatio="xMinYMid meet"
      fill="currentColor"
      className={cn("w-auto shrink-0 overflow-visible", INK[on], className ?? "h-6")}
      style={{ aspectRatio: `${LOCKUP.width} / ${LOCKUP.height}` }}
      role={decorative ? undefined : "img"}
      aria-hidden={decorative ? true : undefined}
      aria-label={decorative ? undefined : site.name}
    >
      <use href={`#${LOCKUP_ID}`} />
    </svg>
  );
}
